(function(){
 const style=document.createElement('style');style.textContent=`.game-icon,.portrait,.item>img,.icon>img{border:3px double #966b35;border-radius:0;padding:5px;box-sizing:content-box;background:#fff7df;margin-right:10px}.item{gap:14px}.gift{border:1px solid #c6ad80;cursor:pointer}.wiki-dialog{width:min(1100px,94vw);max-width:1100px;height:90vh;overflow:auto}.wiki-reader{font-size:15px;line-height:1.7}.wiki-reader table{border-collapse:collapse;display:block;max-width:100%;overflow:auto;margin:18px 0}.wiki-reader td,.wiki-reader th{border:1px solid #d4bf99;padding:9px}.wiki-reader img{image-rendering:pixelated;max-width:100%;height:auto}.wiki-reader a{color:#365c2c;text-decoration:underline}.wiki-reader h2{margin-top:28px;border-bottom:2px solid #d6c09a}.wiki-reader h3{margin-top:20px}.wiki-reader .toc{display:none}`;document.head.append(style);
 let controller=null;
 const allowed=new Set(['P','DIV','SPAN','H2','H3','H4','H5','UL','OL','LI','TABLE','THEAD','TBODY','TR','TD','TH','CAPTION','B','STRONG','I','EM','BR','HR','SMALL','SUP','SUB','DL','DT','DD']);
 function sanitize(html,lang){const doc=new DOMParser().parseFromString(html,'text/html');const host=lang==='en'?'https://stardewvalleywiki.com':'https://pt.stardewvalleywiki.com';
 function build(node){if(node.nodeType===3)return document.createTextNode(node.textContent);if(node.nodeType!==1)return document.createDocumentFragment();if(['SCRIPT','STYLE','IFRAME','FORM','INPUT','BUTTON','OBJECT','LINK','META','SVG'].includes(node.tagName))return document.createDocumentFragment();let el;
 if(node.tagName==='A'){let url;try{url=new URL(node.getAttribute('href'),host);}catch{return document.createTextNode(node.textContent);}if(/(^|\.)stardewvalleywiki\.com$/.test(url.hostname)&&!url.pathname.includes('Special:')&&!url.pathname.includes('Ficheiro:')&&!url.pathname.includes('File:')){el=document.createElement('a');el.href='#';el.onclick=event=>{event.preventDefault();if(url.hash&&url.pathname===location.pathname)return;let title=decodeURIComponent(url.pathname.slice(1)).replaceAll('_',' ');if(url.searchParams.has('title'))title=url.searchParams.get('title');openPage(title,null,url.hostname.startsWith('pt.')?'pt':'en');};}else el=document.createElement('span');}
 else if(node.tagName==='IMG'){try{const url=new URL(node.getAttribute('src'),host);if(url.protocol!=='https:'||!/(^|\.)stardewvalleywiki\.com$/.test(url.hostname))return document.createDocumentFragment();el=document.createElement('img');el.src=url.href;el.alt=node.getAttribute('alt')||'';el.loading='lazy';}catch{return document.createDocumentFragment();}}
 else el=document.createElement(allowed.has(node.tagName)?node.tagName.toLowerCase():'div');
 for(const attr of ['colspan','rowspan'])if(node.hasAttribute(attr)&&/^\d{1,2}$/.test(node.getAttribute(attr)))el.setAttribute(attr,node.getAttribute(attr));for(const child of node.childNodes)el.append(build(child));return el;}
 const result=document.createDocumentFragment();for(const child of doc.body.childNodes)result.append(build(child));return result;}
 async function openPage(title,item,lang='pt',fallback){controller?.abort();controller=new AbortController();const signal=controller.signal;const modal=document.querySelector('#dialog');modal.classList.add('wiki-dialog');const body=document.querySelector('#dialogbody');body.replaceChildren();const header=document.createElement('h1');header.textContent=item?.name||title;body.append(header);if(item?.icon){const icon=document.createElement('img');icon.src=item.icon;icon.alt=item.name;icon.className='game-icon';body.append(icon);}const content=document.createElement('article');content.className='wiki-reader';content.textContent='Carregando informações da Wiki…';body.append(content);if(!modal.open)modal.showModal();
 try{let response=await fetch('/api/wiki?title='+encodeURIComponent(title)+'&lang='+lang,{signal});if(!response.ok&&fallback){response=await fetch('/api/wiki?title='+encodeURIComponent(fallback)+'&lang=en',{signal});}if(!response.ok)throw Error('A Wiki não pôde ser consultada. Verifique a internet e tente novamente.');const page=await response.json();content.replaceChildren(sanitize(page.html,page.language));const source=document.createElement('p');source.textContent='Fonte: Stardew Valley Wiki · '+page.title+' · '+page.license;content.append(source);}catch(error){if(error.name==='AbortError')return;content.textContent=error.message;const retry=document.createElement('button');retry.textContent='Tentar novamente';retry.onclick=()=>openPage(title,item,lang,fallback);content.append(retry);}}
 window.openItemPage=item=>openPage(item.name,item,'pt',item.wikiName||item.name);
 document.addEventListener('click',event=>{const anchor=event.target.closest('a');if(!anchor)return;try{const url=new URL(anchor.href);if(/(^|\.)stardewvalleywiki\.com$/.test(url.hostname)){event.preventDefault();openPage(decodeURIComponent(url.pathname.slice(1)).replaceAll('_',' '),null,url.hostname.startsWith('pt.')?'pt':'en');}}catch{}},true);
 const priorRender=window.render;window.render=function(){priorRender();if(['fishing','foraging','farming','mining','combat'].includes(current)){openPage('Caverna da Maestria',null,'pt','Mastery Cave');}if(current==='wiki'){const search=document.createElement('form');search.className='toolbar';const input=document.createElement('input');input.placeholder='Pesquisar um item ou assunto na Wiki';input.setAttribute('aria-label','Página da Wiki');const button=document.createElement('button');button.textContent='Consultar';search.append(input,button);search.onsubmit=e=>{e.preventDefault();if(input.value.trim())openPage(input.value.trim());};document.querySelector('#content .hero').after(search);}};
 window.detail=(name)=>window.openItemPage({name,wikiName:typeof english!=='undefined'?english[name]:name});
})();
